window.MAGIC_CHUNK_76 = [{"name":"Monstrous Dye","aura_strength":"moderate","aura_school":"conjuration and necromancy","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":2250,"weight":0,"description":"This small bone container is filled with a thick dye. Each container holds enough dye to cover one ornament created with the Grisly Ornament feat. When applied to an ornament, it aids in the ornament's preservation, allowing it to remain effective for an additional 24 hours. Once per day as a free action, a dyed ornament can be commanded to attack a target adjacent to the wearer. A ghostly image of the creature from which the ornament was harvested appears and makes a natural attack against the target, attacking with the wearer's base attack bonus and dealing 2d6 points of damage. This attack can be made in addition to any actions performed by the wielder. An ornament integrated into a wondrous item with the Monstrous Crafter feat can gain this attack ability, but doing so requires two applications of monstrous dye to function properly.","requirements":"Craft Wondrous Items, gentle repose, summon nature's ally IV","cost":1125,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Necklace of Beast's Might, Bones","aura_strength":"moderate","aura_school":"transmutation","cl":7,"slots":["neck"],"groups":["Wondrous Item"],"price":12000,"weight":0,"description":"A necklace of beast's might is a crude necklace made from a particular part (or close analog) of a creature of a specific type: aberrations, animals, dragons, fey, magical beasts, oozes (often made using hardened leftovers), or vermin. Regardless of the parts used to make the necklace, the necklace quietly rattles when a creature of the specific type is within 100 feet of the wearer. In addition, the wearer gains DR 2/— against natural attacks from the associated creature type.","requirements":"Craft Wondrous Items, locate creature, stoneskin","cost":6000,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Necklace of Beast's Might, Claws","aura_strength":"moderate","aura_school":"transmutation","cl":8,"slots":["neck"],"groups":["Wondrous Item"],"price":9000,"weight":0,"description":"A necklace of beast's might is a crude necklace made from a particular part (or close analog) of a creature of a specific type: aberrations, animals, dragons, fey, magical beasts, oozes (often made using hardened leftovers), or vermin. Regardless of the parts used to make the necklace, the necklace quietly rattles when a creature of the specific type is within 100 feet of the wearer. In addition, the wearer gains a +2 morale bonus on attack rolls against the associated creature type.","requirements":"Craft Wondrous Items, locate creature, magic weapon","cost":4500,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Necklace of Beast's Might, Eyes","aura_strength":"faint","aura_school":"divination","cl":5,"slots":["neck"],"groups":["Wondrous Item"],"price":6000,"weight":0,"description":"A necklace of beast's might is a crude necklace made from a particular part (or close analog) of a creature of a specific type: aberrations, animals, dragons, fey, magical beasts, oozes (often made using hardened leftovers), or vermin. Regardless of the parts used to make the necklace, the necklace quietly rattles when a creature of the specific type is within 100 feet of the wearer. In addition, the wearer gains a +5 insight bonus on Knowledge checks to identify creatures of the associated type and on Perception checks opposed by such creatures' Disguise checks.","requirements":"Craft Wondrous Items, locate creature, know the enemy","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Necklace of Beast's Might, Hair","aura_strength":"faint","aura_school":"transmutation","cl":5,"slots":["neck"],"groups":["Wondrous Item"],"price":8000,"weight":0,"description":"A necklace of beast's might is a crude necklace made from a particular part (or close analog) of a creature of a specific type: aberrations, animals, dragons, fey, magical beasts, oozes (often made using hardened leftovers), or vermin. Regardless of the parts used to make the necklace, the necklace quietly rattles when a creature of the specific type is within 100 feet of the wearer. In addition, the wearer gains a +2 competence bonus on Survival checks to track the associated creature type, and the scent special ability, but only to notice odors of the associated creature type.","requirements":"Craft Wondrous Items, locate creature, beast shape I","cost":4000,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Necklace of Beast's Might, Horns","aura_strength":"faint","aura_school":"transmutation","cl":5,"slots":["neck"],"groups":["Wondrous Item"],"price":8000,"weight":0,"description":"A necklace of beast's might is a crude necklace made from a particular part (or close analog) of a creature of a specific type: aberrations, animals, dragons, fey, magical beasts, oozes (often made using hardened leftovers), or vermin. Regardless of the parts used to make the necklace, the necklace quietly rattles when a creature of the specific type is within 100 feet of the wearer. In addition, he wearer gains a +2 bonus on combat maneuvers and to CMD against the associated creature type.","requirements":"Craft Wondrous Items, locate creature, bull's strength","cost":4000,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Necklace of Beast's Might, Scales","aura_strength":"moderate","aura_school":"transmutation","cl":9,"slots":["neck"],"groups":["Wondrous Item"],"price":9000,"weight":0,"description":"A necklace of beast's might is a crude necklace made from a particular part (or close analog) of a creature of a specific type: aberrations, animals, dragons, fey, magical beasts, oozes (often made using hardened leftovers), or vermin. Regardless of the parts used to make the necklace, the necklace quietly rattles when a creature of the specific type is within 100 feet of the wearer. In addition, the wearer gains a +2 insight bonus to AC against attacks made by the associated creature type.","requirements":"Craft Wondrous Items, locate creature, barkskin","cost":4500,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Necklace of Beast's Might, Teeth","aura_strength":"moderate","aura_school":"transmutation","cl":8,"slots":["neck"],"groups":["Wondrous Item"],"price":12000,"weight":0,"description":"A necklace of beast's might is a crude necklace made from a particular part (or close analog) of a creature of a specific type: aberrations, animals, dragons, fey, magical beasts, oozes (often made using hardened leftovers), or vermin. Regardless of the parts used to make the necklace, the necklace quietly rattles when a creature of the specific type is within 100 feet of the wearer. In addition, the wearer gains a +2 bonus on damage rolls against creatures of that type. The wearer's critical hits against such creatures deal 1d6 bleed damage.","requirements":"Craft Wondrous Items, locate creature, magic weapon","cost":6000,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Nest Revealer","aura_strength":"faint","aura_school":"divination","cl":3,"slots":["none"],"groups":["Wondrous Item"],"price":500,"weight":1,"description":"This small vial is sealed with a fine metal cap engraved with the visage of a noble hound. When a few drops of a creature's blood are placed in the vial, it begins to fill on its own, replicating the creature's blood over the span of 1 minute. After 1 minute, the vial shatters and a small fist-sized orb of crystallized blood falls to the ground. This animate orb rolls in the direction of the last location in which the source creature slept for at least 1 hour. The blood travels at a rate of 20 feet per round and can travel up to 10 miles over the span of 5 hours. If the orb doesn't reach the creature's nest within 5 hours, it collapses into a puddle containing enough blood to activate another nest revealer.","requirements":"Craft Wondrous Items, locate creature","cost":250,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Penetrating Whetstone","aura_strength":"moderate","aura_school":"evocation","cl":8,"slots":["none"],"groups":["Wondrous Item"],"price":2000,"weight":1,"description":"This whetstone is made from finely worked obsidian. Sharpening a blade with this whetstone requires 15 minutes of work and grants the weapon the ability to ignore up to 3 points of natural armor for its next five attacks. If the target of the weapon's attack has a natural armor bonus of less than +3, the weapon deals 1 additional point of damage for each point of natural armor below 3 the target has. The process of honing the blade shatters a portion of the whetstone's enchanted obsidian, dispelling its magic and turning it into a mundane whetstone afterward.","requirements":"Craft Wondrous Items, keen edge","cost":1000,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Pocket Prey","aura_strength":"moderate","aura_school":"illusion","cl":10,"slots":["none"],"groups":["Wondrous Item"],"price":6000,"weight":3,"description":"This small container features a stone base with a glass cover. The container can hold half a pound of flesh or similar organic matter, preserving it for up to 24 hours. On command, the container emanates the smell of the contained material out to a 100-foot radius. Additionally, the container lets out a cry every minute, imitating that of an injured member of the variety of the flesh within the container. This cry can be clearly heard up to 150 feet from the container.","requirements":"Craft Wondrous Items, gentle repose, major image","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Monster Hunter's Handbook","pfs_content":0},{"name":"Skelterhide","aura_strength":"strong","aura_school":"enchantment","cl":15,"slots":["shoulders"],"groups":["Wondrous Item"],"price":4500,"weight":5,"description":"This thick hide cloak grants its wearer the divided mind of a skeltercat. While worn, the cloak imparts a +1 resistance bonus on Fortitude and Reflex saves and a +2 resistance bonus on Will saves. In addition, once per round, the wearer can reroll the percentile dice when determining his actions while confused and choose the desired result. Once the cloak is donned, the wearer cannot speak or write; he can communicate only in unintelligible growls. The wearer still understands language as normal. If the wearer suffers from one or more permanent mental afflictions that alter his behavior, such as insanity or the effects of a helm of opposite alignment, for 15 minutes per day he can function as if unaffected by these conditions. This time doesn't need to be used all at once, but must be used in 1-minute increments.","requirements":"Craft Wondrous Items, calm emotions, resistance, blindness/deafness","cost":2250,"destruction":null,"base_item":null,"magic_items":null,"source":"AP 117","pfs_content":0},{"name":"Bottled Sunlight","aura_strength":"faint","aura_school":"evocation","cl":5,"slots":["none"],"groups":["Wondrous Item"],"price":50,"weight":0,"description":"A single jar of bottled sunlight sheds light as a candle. Bottled sunlight can be thrown as a splash weapon, dealing 3d6 points of damage to a target vulnerable to sunlight. Creatures adjacent to the target that are vulnerable to sunlight take 1 point of splash damage. Regardless of its vulnerability to sunlight, a creature directly struck radiates light as a torch for 1 round after being hit. Alternatively, a jar of bottled sunlight can be poured over a 10- foot area to produce light like a lantern for 10 minutes.","requirements":"Craft Wondrous Items, daylight","cost":25,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Rockfall Cloak","aura_strength":"faint","aura_school":"conjuration","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":2500,"weight":1,"description":"A rockfall cloak is fashioned from rigid fabric with a stony texture, and it grants a +2 circumstance bonus on Stealth checks in underground terrain. The wearer can command the cloak to encapsulate him as a free action. The cloak then hardens into a spherical stone shell resembling a smooth boulder that occupies an entire 5-foot square and weighs 200 pounds. The shell has a hardness of 10 and 25 hit points. Any damage from falling or from falling rocks is dealt to the stone shell. If it is destroyed, any remaining damage is transferred to its wearer. A rockfall cloak remains in this stone shell form for 1 hour (or earlier, if the wearer chooses) before crumbling to dust. Once it's used in its stone shell form, a rockfall cloak is destroyed.","requirements":"Craft Wondrous Items, stone shield","cost":1250,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Stonemeld Boots","aura_strength":"moderate","aura_school":"transmutation","cl":9,"slots":["feet"],"groups":["Wondrous Item"],"price":3500,"weight":1,"description":"The wearer of a pair of stonemeld boots gains a +4 bonus to CMD against bull rush, drag, reposition, and trip combat maneuvers. Additionally, once per day as a swift action, the boots can be activated to grant the wearer a climb speed of 10 feet on any natural stone surface (but not manufactured stone surfaces like brick walls) for 30 minutes. A creature using stonemeld boots to climb in this fashion leaves obvious deformities in the rock surface. Anyone attempting to track a wearer of stonemeld boots moving in this fashion treats the base DC as though the tracks were left in soft earth, and takes no penalties for time elapsed since the tracks were made.","requirements":"Craft Wondrous Items, transmute rock to mud","cost":1750,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Blightburn Arrow","aura_strength":"moderate","aura_school":"evocation and necromancy","cl":7,"slots":["none"],"groups":["Weapon"],"price":3000,"weight":0.1,"description":"This +2 arrow is fitted with a head of pure, crystallized blightburn. Unless contained in a lead-lined case or quiver, the arrow deals 1 point of fire damage per round to the creature carrying it. If the arrow hits, the arrowhead embeds itself in the target, dealing an additional 3d6 points of fire damage. The arrow continues to deal 2d6 points of fire damage each round for the following 6 rounds unless it's pulled out as a move action. A creature taking recurring damage from a blightburn arrow also suffers from low-level blightburn radiation as long as the arrow remains embedded. An arrow that misses its target can be recovered as normal, but an arrow removed after hitting a target is destroyed.","requirements":"Craft Magic Arms and Armor, fester, fireball","cost":1500,"destruction":null,"base_item":"+2 arrow","magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Polychrome Cover","aura_strength":"moderate","aura_school":"illusion","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":2000,"weight":4,"description":"This multicolored tarp is made from intricately woven cloth that gives its exterior the texture of stonework. It covers a 10-foot by  10-foot area and can be placed vertically, magically supporting its own weight. A polychrome cover magically takes on the same coloration of nearby stone, imitating any terrain it's in contact with. The coloration of the cover is an illusion effect that can be disbelieved (Will DC 16). Those who successfully disbelieve the effect instead see the cover's true coloration. When a polychrome cover is crafted, the maker designates any number of creatures present at its creation to be immune to the cover's illusory effect. The crafter can instead exclude a specific race from the item's illusion. Most polychrome covers are set to exclude svirfneblin.","requirements":"Craft Wondrous Items, hallucinatory terrain","cost":1000,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Amulet of Radiation Absorption","aura_strength":"moderate","aura_school":"abjuration and conjuration","cl":10,"slots":["neck"],"groups":["Wondrous Item"],"price":45000,"weight":1,"description":"This amulet features a large, ragged stone that was harvested from highly radioactive regions of the Darklands and that glows with a faint green light. The wearer is rendered immune to the effects of all forms of radiation. Additionally, for each minute the wearer is exposed to radiation, the amulet absorbs 1 charge of radioactive energy. The amulet can hold up to 5 charges. Charges naturally dissipate at a rate of 1 charge per 24 hours. As a standard action, the wearer can expend 1 charge in order to fire a ray of concentrated radiation from the amulet. Treat this as a ranged touch attack with a range of 60 feet. The wearer can choose any one of the following effects, as outlined below. Blightburn: The target takes 6d6 points of fire damage. Caphorite: The target must succeed at a DC 14 Fortitude save or be blinded for 1d4 rounds. Lazurite: The target takes 2d6 points of negative energy damage, and if it dies in the next hour, there is a 50% chance it rises as a ghoul 1d4 rounds later. Surface: The target takes 1d2 points of Strength and Constitution damage.","requirements":"Craft Wondrous Items, radiation ward, remove radioactivity","cost":22500,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Cavern Compass","aura_strength":"moderate","aura_school":"divination","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":15000,"weight":1,"description":"Made specifically for those who frequently navigate the mazelike tunnels that wind throughout Nar-Voth, these compasses are made from stone sourced from the Darklands. However, instead of featuring the four cardinal directions, the compass's circumference is adorned with several small pictographs. To use a cavern compass, the bearer must be at an intersection of tunnels or caverns somewhere underground, and must hold it in his hand and speak the name of his desired destination. The destination must be well known enough to be likely to appear on a map of the area, such as a settlement or a prominent ruin, or else must be a location with which the holder is intimately familiar. For the next mile, the needle of the cavern compass points down whichever passageway most efficiently leads to the chosen destination. Additionally, if the passage contains any of the following hazards over the course of 1 mile, a corresponding pictograph glows with a faint light: magma, molds or slimes, radiation, sudden vertical passages, or water hazards. If a passage further splits into multiple pathways within 1 mile, the cavern compass selects whichever one results in being closest to the destination after 1 mile and provides information about hazards only down that route.","requirements":"Craft Wondrous Items, find the path","cost":7500,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Earthquake Boots","aura_strength":"strong","aura_school":"evocation","cl":15,"slots":["feet"],"groups":["Wondrous Item"],"price":67500,"weight":1,"description":"These thick hide boots allow the wearer to detect unseen enemies, and they provide a final line of defense against overwhelming foes. The wearer gains tremorsense with a range of up to 60 feet as long as he is standing on solid ground. Additionally, once per day, by stomping repeatedly on an earthen or stone surface as a full-round action that provokes attacks of opportunity, the wearer can cast earthquake as a spell-like ability.","requirements":"Craft Wondrous Items, earthquake, see invisibility","cost":33750,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Ghoulbane Belt","aura_strength":"moderate","aura_school":"conjuration","cl":7,"slots":["belt"],"groups":["Wondrous Item"],"price":20000,"weight":1,"description":"Due to the toxic nature of many environments found within the Darklands, this belt is designed to protect its wearer from exotic diseases, paralyzing attacks, and poisonous molds. The wearer gains a +2 bonus on saving throws to resist disease, paralysis, and poison. This bonus increases to +4 on saving throws to resist such effects caused by molds or slimes. Additionally, the wearer can cast a single spell from the following list as a spell-like ability once per day: neutralize poison, remove disease, or remove paralysis. Activating this ability is a purely mental action that can be taken even while paralyzed or otherwise helpless. The chosen spell affects only the belt's wearer.","requirements":"Craft Wondrous Items, neutralize poison, remove disease, remove paralysis","cost":10000,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Helm of Ooze","aura_strength":"moderate","aura_school":"enchantment","cl":10,"slots":["head"],"groups":["Wondrous Item"],"price":21500,"weight":3,"description":"This bulky, rusted helm incorporates a pair of goggles that sit on the wearer's brow. The wearer of a helm of ooze control gains a limited ability to telepathically command oozes. Once per day as a standard action, the wearer can attempt to gain control over a single ooze within 60 feet. The ooze must succeed at a DC 17 Will save or fall under the wearer's mental control. This compulsion affects even mindless oozes. The control offered by the helm is very limited, and the wearer is able to issue only one of the following commands at a time, as a move action, to a controlled ooze within 60 feet. Attack: The ooze attacks the nearest creature. Halt: The ooze remains in place. It doesn't take any actions but isn't considered helpless. Move: The ooze moves toward a point in space that the wearer can see. The wearer can control up to 20 Hit Dice worth of oozes at any given time. An ooze with 5 or more Hit Dice can attempt a new Will save each day to free itself from the wearer's control. An ooze ordered to halt receives a new Will save to overcome the helm's control if attacked. Oozes with an Intelligence score, as well as those with 11 or more Hit Dice, are immune to this effect. The wearer can issue a command to multiple controlled oozes with a single move action, but if he does, each ooze receives the same command. Oozes that have been issued a command continue to follow that command until a new command is issued or they are released from the helm's control. Removing the helm doesn't release the oozes from control, but the helm must be worn to issue new commands. If 24 hours pass without the helm being worn, then all affected oozes are released from control.","requirements":"Craft Wondrous Items, greater command","cost":10750,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Robe of Magma","aura_strength":"strong","aura_school":"conjuration","cl":15,"slots":["body"],"groups":["Wondrous Item"],"price":112000,"weight":1,"description":"These striking black robes are lined with glowing cracks, and resemble flows of partially cooled magma. They allow the wearer not only to survive within areas of lava and magma, but also to conjure molten rock from the earth. The wearer gains fire resistance 20 and immunity to fire damage from lava and magma. Additionally, while submerged in lava or magma, the wearer can breathe normally, gains a +5 bonus on Swim checks, and can see through the substance as clearly as if it were water. Once per day as a full-round action, the wearer of a robe of magma can conjure a great burst of magma from deep below the surface. This ability can be used only while the wearer is on the Material Plane, and only while on solid ground on a planetary body. The deeper beneath a planet's surface the wearer is, the sooner the magma arrives. If the wearer uses this ability while 8,000 feet (or more) below the surface, the magma arrives instantaneously. If he uses it between 2,000 and 8,000 feet below the surface, the magma arrives at the beginning of the wearer's next turn. If he uses it on the surface or down to 2,000 feet below the surface, the magma arrives in 1d4 rounds. Once the magma arrives, it bursts from the ground in a geyser that sprays up to 40 feet in height and showers a 20-foot radius centered on the location of the wearer when this ability was activated. This deals 20d6 points of fire damage to creatures in the area (Reflex DC 22 half) and creates a shallow pool of lava in the area of the burst. The magma geyser continues for 1d3 rounds. For each round that the geyser continues, the pool of lava expands its radius by 10 feet. Creatures that enter the pool of lava or begin their turn in this area take 2d6 points of fire damage. Once the magma geyser stops, this pool cools and hardens over the course of 1d3 rounds. The magma arrives through an extradimensional space and doesn't impact any features or terrain located under its point of conjuration.","requirements":"Craft Wondrous Items, protection from energy, wall of lava","cost":56000,"destruction":null,"base_item":null,"magic_items":null,"source":"Heroes of the Darklands","pfs_content":0},{"name":"Eyjatas","aura_strength":"overwhelming","aura_school":"all","cl":26,"slots":["none"],"groups":["Artifact, Major"],"price":0,"weight":4,"description":"Barbatos wields a potent weapon named Eyjatas, a +4 speed unholy quarterstaff embedded with innumerable inhuman eyeballs. Three times per day when striking a creature with Eyjatas, its wielder can rip the target's eyes out, permanently blinding it and dealing 2d6 points of bleed damage. A creature can resist this effect with a successful DC 30 Fortitude save, but no save is allowed if the attack was a confirmed critical hit. Once Eyjatas rips out a creature's eyes, it functions as a bane weapon against that target. Three times per day, the wielder of Eyjatas can cast prying eyes. In addition, the wielder can use arcane eye at will, even on other planes viewed through scrying, and can use eyebite (DC 20) at will within 30 feet of the arcane eye.","requirements":null,"cost":0,"destruction":"To destroy Eyjatas, the quarterstaff's dozens of eyes must be blinded by the purifying light of an unwavering truth spoken by an immortal that has only ever spoken lies in its life. Once the eyes are blinded in this way, the staff must be hurled into a magical portal that has no entrance and that leads nowhere.","base_item":"+4 speed unholy quarterstaff","magic_items":null,"source":"Bestiary 6","pfs_content":0},{"name":"The Eclipsing Eye","aura_strength":"overwhelming","aura_school":"all","cl":30,"slots":["none"],"groups":["Artifact, Major"],"price":0,"weight":20,"description":"The Eclipsing Eye is a +4 adamantine axiomatic unholy wounding heavy mace; it is a token of esteem and power granted by Asmodeus himself to the governor of Hell's greatest city. It allows the wielder to command allegiance as per a rod of rulership with an unlimited duration when activated in Hell. Outside of Hell, it remains limited to 500 total minutes of this effect, but doesn't crumble to dust if these minutes are used up. Every hour it spends in Hell restores 1 minute of expended duration. When used as a weapon, The Eclipsing Eye has a critical multiplier of x3. The Eclipsing Eye automatically casts blindness (as per blindness/deafness heightened to 9th level, save DC 23) on the first creature it strikes each round. The Eclipsing Eye is Dispater's rod of office, and he can summon it to his hand as a free action from any distance, even across planar boundaries. As long as he wields it, all lawful evil, neutral evil, and lawful neutral creatures treat him as if he were under a sanctuary spell (CL 30th, save DC 23 as if heightened to a 9th level spell). Three times per day, The Eclipsing Eye can create any of the following spell effects, heightened to 9th level as per the Heighten Spell feat: calm emotions, demand, discern lies, and discern location.","requirements":null,"cost":0,"destruction":"Asmodeus can will the destruction of The Eclipsing Eye as a free action, but otherwise it can be destroyed only by immersing it in the headwaters of the River Styx for a century, allowing the artifact to rust away.","base_item":"+4 adamantine axiomatic unholy wounding heavy mace","magic_items":null,"source":"Bestiary 6","pfs_content":0},{"name":"Horn of Lies","aura_strength":"overwhelming","aura_school":"all","cl":30,"slots":["none"],"groups":["Artifact, Major"],"price":0,"weight":15,"description":"This horn can be sounded three times per day as a swift or move action to function as a greater horn of blasting with no chance of exploding and an effect duration of 1 minute. Creatures deafened by the horn hear whispers and falsehoods echoing in their minds, twisting their perceptions; they treat all other creatures as if they had concealment and take a -4 penalty on saves against mind-affecting effects as long as they remain deaf. In addition, any competence or insight bonuses are treated as penalties instead until they regain their hearing. The horn can be sounded three additional times per day to grant allies within 60 feet a +4 bonus on saves against divine spells, while enemies within 60 feet become unable to tell the truth (Will DC 25 negates). This includes verbal, written, and any other form of communication, but doesn't prevent saying things that are neither true nor untrue, such as commands, questions, and verbal components of spells. While compelled to falsehood, Geryon's enemies also become paranoid and treat no one as their ally; thus, they are unable to provide or benefit from flanking, teamwork feats, or the aid another action, and always attempt to save against harmless effects. Affected creatures are unable to cast divine spells or activate domain powers unless they worship an archdevil. This effect lasts 1 minute. This is a sonic mind-affecting curse effect.","requirements":null,"cost":0,"destruction":"If the Horn of Lies is sounded by a chaotic good divine spellcaster within the Silent Cairns of Elysium, it shatters into 13 fragments, each of which transforms into a serpentine monster. If these 13 serpents are slain within 24 hours, the artifact is destroyed-but if even one serpent remains alive, the Horn of Lies is restored and returned to Asmodeus's keeping in Hell.","base_item":null,"magic_items":null,"source":"Bestiary 6","pfs_content":0},{"name":"Visineir","aura_strength":"overwhelming","aura_school":"all","cl":30,"slots":["none"],"groups":["Artifact, Major"],"price":0,"weight":1,"description":"This adamantine quill pen is the greatest weapon Mephistopheles has in the corruption of souls. As a full-round action that doesn't provoke attacks of opportunity, he can use it to inscribe a magic circle against good (or chaos), place a mark of justice, or pen an infernal contract. These contracts can grant any number of boons, but typically do so in the form of a wish spell or the devilbound template. Visineir can be wielded as a +1 adamantine keen wounding dagger, but Mephistopheles rarely does so, preferring his trident in battle. The quill can store a sample of blood from every creature it strikes, storing up to 33 blood samples at a time. The quill gains the bane special ability against any creature whose blood it stores, and it marks the target as if Mephistopheles had used a witch's scar hex on it, allowing him to use his spell-like abilities on that creature with a range of 1 mile (or with unlimited range, if the creature is in Caina). Mephistopheles can expend one stored blood sample as a full-round action to inscribe a symbol spell of any type he wishes, or to call the creature to him as if he had cast greater planar binding (regardless of the creature's actual type-this isn't limited to calling outsiders).","requirements":null,"cost":0,"destruction":"If Visineir is used to pen a contract that results in Asmodeus having to void the creation of Mephistopheles, the quill crumbles away to ashes, as does Mephistopheles himself.","base_item":"+1 adamantine keen wounding dagger","magic_items":null,"source":"Bestiary 6","pfs_content":0},{"name":"Usher of the Black Rain","aura_strength":"overwhelming","aura_school":"all","cl":29,"slots":["none"],"groups":["Artifact, Major"],"price":0,"weight":12,"description":"Apollyon's weapon is the Usher of the Black Rain. He can cause this weapon to shift from a scythe to a composite longbow (Str +16) as a move action, but in both forms the Usher is a +5 unholy wounding weapon. As a longbow, it creates ammunition automatically as it is fired. Against foes who are currently suffering from a disease, the Usher of the Black Rain deals an additional 6 points of profane damage with each hit.","requirements":null,"cost":0,"destruction":"The Usher of the Black Rain burns to ash if Apollyon's cloak (which was stitched from the flesh of the angels whose souls empower his bow) is brought to Nirvana, washed clean there, and then buried while intoning each dead angel's long-forgotten name.","base_item":"+5 unholy wounding scythe, +5 unholy wounding longbow","magic_items":null,"source":"Bestiary 6","pfs_content":0},{"name":"Lamentation of the Faithless","aura_strength":"overwhelming","aura_school":"all","cl":28,"slots":["none"],"groups":["Artifact, Major"],"price":0,"weight":8,"description":"Szuriel's weapon is Lamentation of the Faithless, a black-bladed +5 speed unholy greatsword. When using the blade to attack, Szuriel regains 1d6 hit points with each successful hit. If Szuriel presents her sword as a standard action, all creatures within 60 feet that view it are blinded and affected by crushing despair for 1d4+1 rounds unless they succeed at a DC 30 Will save. Creatures with the good subtype and divine spellcasters take a -4 penalty on this save. As a standard action, Szuriel can call the sword to her hand from any distance, including across planar boundaries.","requirements":null,"cost":0,"destruction":"The sword shatters and sublimates if it is ever placed in the empty, walled garden at the summit of Heaven's mountain by a risen, repentant fiend.","base_item":"+5 speed unholy greatsword","magic_items":null,"source":"Bestiary 6","pfs_content":0},{"name":"Sigil of Kraggodan","aura_strength":"moderate","aura_school":"abjuration","cl":10,"slots":["ring"],"groups":["Ring"],"price":16000,"weight":0,"description":"This adamantine band is capped with a stone sigil of the first clan to settle the Sky Citadel of Kraggodan. This ring is keyed to interact with several devices and traps within the vaults-storehouses of ancient history and family wealth-of the Sky Citadel. The ring grants its wearer acid resistance 10. Three times per day as a swift action, the wearer can make himself undetectable by crafted and magical traps and creatures of the construct type for the following minute. This functions like greater invisibility within these limits and also prevents the character's weight or presence from triggering traps.","requirements":"Forge Ring, resist energy, sanctuary","cost":8000,"destruction":null,"base_item":null,"magic_items":null,"source":"AP 118","pfs_content":0},{"name":"The Enthroned King","aura_strength":"strong","aura_school":"evocation and necromancy","cl":13,"slots":["none"],"groups":["Artifact, Minor","Intelligent Item"],"price":0,"weight":2,"description":"Roiling blue smoke fills this small glass bottle, occasionally forming an aged face that vanishes just as quickly. So long as the bottle is worn openly on a creature's body, the Enthroned King's inspiring presence grants its carrier a +1 luck bonus on all ability checks, saving throws, and skill checks. The spirit trapped within is utterly devoted to protecting dwarves, and especially the Sky Citadel of Kraggodan. Three times per day, the Enthroned King may invest his wielder with some of his own immortal life force, granting her 1d10+10 temporary hit points.","requirements":null,"cost":0,"destruction":"The Enthroned King must prostrate himself before a powerful servant of Malgrim, the dwarven guardian of the afterlife-a task that requires him to once again have a body rather than his current form of only dust and breath.","base_item":null,"magic_items":null,"intelligent_item":{"al":"neutral good","int":16,"wis":16,"cha":19,"ego":16,"communication":null,"senses":"60 ft. (darkvision)","powers":null,"languages":"Common, Dwarven, Terran, Undercommon"},"source":"AP 118","pfs_content":0},{"name":"Charm of the Thriceborn","aura_strength":"moderate","aura_school":"divination","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":2400,"weight":0,"description":"A creature carrying this knot-shaped charm for 3 full days becomes its owner until he loses possession of it. A creature can only be the owner of a single charm of the thriceborn. At the start of each day, the charm's owner rolls 3d20 and keeps their results as his charmed dice. Once during that day, instead of rolling a d20, the charm's owner can instead use the result of one of the three charmed dice, randomly selected (roll 1d3 to choose).","requirements":"Craft Wondrous Items, threefold sight","cost":1200,"destruction":null,"base_item":null,"magic_items":null,"source":"Legacy of the First World","pfs_content":0},{"name":"Rod of the Thriceborn, Lesser","aura_strength":"moderate","aura_school":"divination","cl":5,"slots":["none"],"groups":["Rod"],"price":2500,"weight":5,"description":"The wielder of this elongated triangular prism can cast up to three spells per day for which the spell's targets must roll three times for their saving throws and take the middle of the three results, as per threefold sight. A lesser rod of the thriceborn can affect spells up to 3rd level, a rod of the thriceborn can affect spells up to 6th level, and a greater rod of the thriceborn can affect spells up to 9th level. A rod of the thriceborn can't be used in conjunction with metamagic rods or the Persistent Spell feat.","requirements":"Craft Rod, threefold sight","cost":1250,"destruction":null,"base_item":null,"magic_items":null,"source":"Legacy of the First World","pfs_content":0},{"name":"Rod of the Thriceborn","aura_strength":"moderate","aura_school":"divination","cl":5,"slots":["none"],"groups":["Rod"],"price":6500,"weight":5,"description":"The wielder of this elongated triangular prism can cast up to three spells per day for which the spell's targets must roll three times for their saving throws and take the middle of the three results, as per threefold sight. A lesser rod of the thriceborn can affect spells up to 3rd level, a rod of the thriceborn can affect spells up to 6th level, and a greater rod of the thriceborn can affect spells up to 9th level. A rod of the thriceborn can't be used in conjunction with metamagic rods or the Persistent Spell feat.","requirements":"Craft Rod, threefold sight","cost":3250,"destruction":null,"base_item":null,"magic_items":null,"source":"Legacy of the First World","pfs_content":0},{"name":"Rod of the Thriceborn, Greater","aura_strength":"moderate","aura_school":"divination","cl":5,"slots":["none"],"groups":["Rod"],"price":19500,"weight":5,"description":"The wielder of this elongated triangular prism can cast up to three spells per day for which the spell's targets must roll three times for their saving throws and take the middle of the three results, as per threefold sight. A lesser rod of the thriceborn can affect spells up to 3rd level, a rod of the thriceborn can affect spells up to 6th level, and a greater rod of the thriceborn can affect spells up to 9th level. A rod of the thriceborn can't be used in conjunction with metamagic rods or the Persistent Spell feat.","requirements":"Craft Rod, threefold sight","cost":9750,"destruction":null,"base_item":null,"magic_items":null,"source":"Legacy of the First World","pfs_content":0},{"name":"Ribbon of the Three","aura_strength":"moderate","aura_school":"transmutation","cl":9,"slots":["head"],"groups":["Wondrous Item"],"price":60000,"weight":0,"description":"This green ribbon is fashioned in the shape of Magdh's three-pointed knot. The wearer gains three faces that each represent a different aspect of her personality, as if constantly under the effect of threefold face.","requirements":"Craft Wondrous Items, threefold face","cost":30000,"destruction":null,"base_item":null,"magic_items":null,"source":"Legacy of the First World","pfs_content":0},{"name":"Clandestine Horseshoes","aura_strength":"faint","aura_school":"illusion","cl":3,"slots":["feet"],"groups":["Wondrous Item"],"price":6000,"weight":12,"description":"If a creature wearing these dull gray horseshoes remains stationary for 1 round, the creature and its rider, if any, gain a +10 bonus on Stealth checks for 1 round. In addition, once per day, the rider of a mount wearing clandestine horseshoes can turn both himself and his mount invisible, as invisibility. All four shoes must be worn by the same creature for the magic to be effective.","requirements":"Craft Wondrous Items, invisibility","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Legacy of the First World","pfs_content":0},{"name":"Hood of Privacy","aura_strength":"strong","aura_school":"abjuration","cl":15,"slots":["head"],"groups":["Wondrous Item"],"price":120000,"weight":1,"description":"This voluminous silver hood shimmers like a scattered handful of diamonds. The hood completely covers the wearer's face, hiding his identity, but doesn't impair the wearer's senses. The wearer gains a +4 bonus on saving throws against mind-affecting effects. The wearer is immediately aware when someone attempts to gain information about him through a divination spell or effect, such as scrying. As a swift action, the wearer can reduce the hood's saving throw bonus by 1 to thwart such a divination attempt, providing whatever false information the wearer desires to the diviner, or even to conceal the information entirely as though the wearer were undetectable to the divination effect. The creature using the divination effect can attempt a DC 26 Will save to learn that the information is fabricated or concealed. Expended bonuses return at a rate of 1 per week.","requirements":"Craft Wondrous Items, detect scrying, mind blank","cost":60000,"destruction":null,"base_item":null,"magic_items":null,"source":"Legacy of the First World","pfs_content":0},{"name":"Whispering Gloves","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["hands"],"groups":["Wondrous Item"],"price":1000,"weight":1,"description":"These supple silk gloves are skintight. As a standard action, the wearer can deliver a complex secret message to a single target that can see the wearer as if he had succeeded at a DC 20 Bluff check. This message is conveyed in a series of rapid, complicated hand gestures that the target automatically understands. Creatures that see the wearer send a message can attempt a DC 20 Sense Motive check to notice that the wearer is delivering a secret message and decipher it.","requirements":"Craft Wondrous Items, message","cost":500,"destruction":null,"base_item":null,"magic_items":null,"source":"Legacy of the First World","pfs_content":0},{"name":"Caparison of Resistance +1","aura_strength":"faint","aura_school":"abjuration","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":2700,"weight":4,"description":"This garment is intended for a horse or similar quadruped, but it can change size and shape to fit any four-legged creature ranging from Small to Huge in size. When worn, a caparison of resistance offers the wearer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will). This bonus on saving throws also applies to a single rider who is mounted on the creature (in the case of multiple riders, the resistance bonus isn't shared at all and applies only to the mount).","requirements":"Craft Wondrous Items, resistance, creator's caster level must be at least three times the cloak's bonus","cost":1350,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Caparison of Resistance +2","aura_strength":"faint","aura_school":"abjuration","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":10800,"weight":4,"description":"This garment is intended for a horse or similar quadruped, but it can change size and shape to fit any four-legged creature ranging from Small to Huge in size. When worn, a caparison of resistance offers the wearer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will). This bonus on saving throws also applies to a single rider who is mounted on the creature (in the case of multiple riders, the resistance bonus isn't shared at all and applies only to the mount).","requirements":"Craft Wondrous Items, resistance, creator's caster level must be at least three times the cloak's bonus","cost":5400,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Caparison of Resistance +3","aura_strength":"faint","aura_school":"abjuration","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":24300,"weight":4,"description":"This garment is intended for a horse or similar quadruped, but it can change size and shape to fit any four-legged creature ranging from Small to Huge in size. When worn, a caparison of resistance offers the wearer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will). This bonus on saving throws also applies to a single rider who is mounted on the creature (in the case of multiple riders, the resistance bonus isn't shared at all and applies only to the mount).","requirements":"Craft Wondrous Items, resistance, creator's caster level must be at least three times the cloak's bonus","cost":12150,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Caparison of Resistance +4","aura_strength":"faint","aura_school":"abjuration","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":43200,"weight":4,"description":"This garment is intended for a horse or similar quadruped, but it can change size and shape to fit any four-legged creature ranging from Small to Huge in size. When worn, a caparison of resistance offers the wearer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will). This bonus on saving throws also applies to a single rider who is mounted on the creature (in the case of multiple riders, the resistance bonus isn't shared at all and applies only to the mount).","requirements":"Craft Wondrous Items, resistance, creator's caster level must be at least three times the cloak's bonus","cost":21600,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Caparison of Resistance +5","aura_strength":"faint","aura_school":"abjuration","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":67500,"weight":4,"description":"This garment is intended for a horse or similar quadruped, but it can change size and shape to fit any four-legged creature ranging from Small to Huge in size. When worn, a caparison of resistance offers the wearer magic protection in the form of a +1 to +5 resistance bonus on all saving throws (Fortitude, Reflex, and Will). This bonus on saving throws also applies to a single rider who is mounted on the creature (in the case of multiple riders, the resistance bonus isn't shared at all and applies only to the mount).","requirements":"Craft Wondrous Items, resistance, creator's caster level must be at least three times the cloak's bonus","cost":33750,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Cloak of Heavenly Fire","aura_strength":"faint","aura_school":"conjuration","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":6000,"weight":1,"description":"This white silk cloak shimmers with divine energy. Once per day as an immediate action, the wearer of a cloak of heavenly fire can cause it to flash with flames as another creature touches the wearer or strikes the wearer with a melee attack. These flames deal 1d8+5 points of fire damage to the creature that touched the wearer. If the creature subjected to this damage is evil, it takes an additional 1d8+5 points of damage as the fire glows with golden light-this additional damage is divine in nature and not subject to energy resistance or immunity. A target that succeeds at a DC 15 Reflex save takes half the total damage. Once per day as a standard action, the wearer of a cloak of heavenly fire can also use the magic to cure wounds, restoring 2d8+5 hit points to a touched creature.","requirements":"Craft Wondrous Items, cure moderate wounds, fire shield","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Rostland Edge","aura_strength":"moderate","aura_school":"evocation and transmutation","cl":10,"slots":["none"],"groups":["Weapon"],"price":21820,"weight":3,"description":"Crafted to defend against enemies seeking to damage it rather than its wielder, a Rostland edge is a +2 countering impervious Aldori dueling sword. If the weapon is ever destroyed, it explodes with tremendous force, dealing 10d6 points of fire damage to every creature within a 20-foot-radius spread (Reflex DC 14 half).","requirements":"Combat Reflexes, Craft Magic Arms and Armor, cat's grace, fabricate, fireball, make whole","cost":11070,"destruction":null,"base_item":"+2 countering impervious Aldori dueling sword","magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Swordlord's Cloak +1","aura_strength":"faint","aura_school":"abjuration and divination","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":4000,"weight":1,"description":"This exotic, fur-trimmed cloak is decorated with golden filigree. In addition to offering magical protection, the cloak guides a skilled wearer's blade to block attacks. Such cloaks are often commissioned by Aldori Academy graduates when they attain swordlord status. A swordlord's cloak acts as a cloak of resistance. In addition, whenever the wearer is benefiting from the defensive parry class feature, he receives an insight bonus to his AC equal to the cloak's resistance bonus.","requirements":"Craft Wondrous Items, anticipate peril, resistance","cost":2000,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Swordlord's Cloak +2","aura_strength":"faint","aura_school":"abjuration and divination","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":16000,"weight":1,"description":"This exotic, fur-trimmed cloak is decorated with golden filigree. In addition to offering magical protection, the cloak guides a skilled wearer's blade to block attacks. Such cloaks are often commissioned by Aldori Academy graduates when they attain swordlord status. A swordlord's cloak acts as a cloak of resistance. In addition, whenever the wearer is benefiting from the defensive parry class feature, he receives an insight bonus to his AC equal to the cloak's resistance bonus.","requirements":"Craft Wondrous Items, anticipate peril, resistance","cost":8000,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Swordlord's Cloak +3","aura_strength":"faint","aura_school":"abjuration and divination","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":37000,"weight":1,"description":"This exotic, fur-trimmed cloak is decorated with golden filigree. In addition to offering magical protection, the cloak guides a skilled wearer's blade to block attacks. Such cloaks are often commissioned by Aldori Academy graduates when they attain swordlord status. A swordlord's cloak acts as a cloak of resistance. In addition, whenever the wearer is benefiting from the defensive parry class feature, he receives an insight bonus to his AC equal to the cloak's resistance bonus.","requirements":"Craft Wondrous Items, anticipate peril, resistance","cost":18500,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0},{"name":"Swordlord's Cloak +4","aura_strength":"faint","aura_school":"abjuration and divination","cl":5,"slots":["shoulders"],"groups":["Wondrous Item"],"price":64000,"weight":1,"description":"This exotic, fur-trimmed cloak is decorated with golden filigree. In addition to offering magical protection, the cloak guides a skilled wearer's blade to block attacks. Such cloaks are often commissioned by Aldori Academy graduates when they attain swordlord status. A swordlord's cloak acts as a cloak of resistance. In addition, whenever the wearer is benefiting from the defensive parry class feature, he receives an insight bonus to his AC equal to the cloak's resistance bonus.","requirements":"Craft Wondrous Items, anticipate peril, resistance","cost":32000,"destruction":null,"base_item":null,"magic_items":null,"source":"Adventurer's Guide","pfs_content":0}];
